    /// <summary>
    /// Finds the icon for a star's key: this class first, then the technology logos.
    /// </summary>
    /// <returns>What to draw, or null when no icon has that key (a test makes sure every star has one).</returns>
    public static ResolvedIcon? Find(string key)
    {
        // STEP 1 of 2: the skills-map icons (the extra logo and the generic glyphs).
        var own = Icons.FirstOrDefault(i => string.Equals(i.Key, key, StringComparison.OrdinalIgnoreCase));
        if (own is not null)
        {
            return new ResolvedIcon(own.SymbolId, own.Fill, own.OnDark);
        }

        // STEP 2 of 2: the logos already drawn once for the page's background, which keep their brand colour.
        var logo = TechLogoData.Logos.FirstOrDefault(l => string.Equals(l.Key, key, StringComparison.OrdinalIgnoreCase));
        return logo is null ? null : new ResolvedIcon(logo.SymbolId, logo.Hex, false);
    }
